#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "syrk.h"


/* Array initialization. */
static
void init_array(int n, int m,
		DATA_TYPE *alpha,
		DATA_TYPE *beta,
		DATA_TYPE POLYBENCH_2D(C,N,N,n,n),
		DATA_TYPE POLYBENCH_2D(A,N,M,n,m))
{
  int i, j;

  *alpha = 1.5;
  *beta = 1.2;
  for (i = 0; i < n; i++)
    for (j = 0; j < m; j++)
      A[i][j] = (DATA_TYPE) ((i*j+1)%n) / n;
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++)
      C[i][j] = (DATA_TYPE) ((i*j+2)%m) / m;
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_2D(C,N,N,n,n))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("C");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
	if ((i * n + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, C[i][j]);
    }
  POLYBENCH_DUMP_END("C");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_syrk[[gnu::flatten, gnu::noinline]](int n, int m,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,N,N,n,n),
		 DATA_TYPE POLYBENCH_2D(A,N,M,n,m))
{
  /* Use PolyBench loop bounds (may differ from raw n/m when running
     in various modes, e.g., reduced-size verification). */
  const int n_ = _PB_N;
  const int m_ = _PB_M;

  int i, j, k;

//BLAS PARAMS
//TRANS = 'N'
//UPLO  = 'L'
// =>  Form  C := alpha*A*A**T + beta*C.
//A is NxM
//C is NxN
//
// Optimizations applied:
// 1. Loop reordering (j–k instead of k–j) so that the innermost loop
//    walks contiguously in memory along rows of A, improving cache
//    utilization and enabling efficient vectorization.
// 2. Fusion of the beta scaling and rank-k update for each C[i][j],
//    reducing the number of passes over C.
// 3. Row-pointer temporaries (Ci, Ai, Aj) to avoid repeated address
//    arithmetic and help the compiler keep values in registers.
// 4. OpenMP parallelization of the outer i-loop. Each iteration
//    operates on a distinct row of C and only reads A, so there are
//    no data races. If compiled without -fopenmp, the pragma is
//    ignored by GCC/Clang and the code remains sequential.
//
#pragma scop
#pragma omp parallel for private(j, k) schedule(static)
  for (i = 0; i < n_; i++) {
    /* Pointers to the current row of C and A.
       Mark Ci as restrict because this is the only pointer used
       to modify row i of C inside the parallel region. */
    DATA_TYPE *restrict Ci = C[i];
    const DATA_TYPE *Ai = A[i];

    /* We compute each C(i,j) in place as:
         C(i,j) = beta * C(i,j) + alpha * dot(A(i,*), A(j,*))
       Only the lower triangle (j <= i) is updated, matching the
       original BLAS SYRK semantics with UPLO = 'L'. */
    for (j = 0; j <= i; j++) {
      const DATA_TYPE *Aj = A[j];

      /* Load and scale C(i,j) by beta once, then accumulate the
         dot product contribution in a register. This preserves the
         per-element operation order over k from the original code:
         we start from beta*C(i,j) and add the same sequence of
         alpha*A(i,k)*A(j,k) terms. */
      DATA_TYPE cij = Ci[j] * beta;

      /* Inner dot-product loop: walks contiguously along Ai and Aj. */
#pragma GCC ivdep
      for (k = 0; k < m_; k++) {
        cij += alpha * Ai[k] * Aj[k];
      }

      Ci[j] = cij;
    }
  }
#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int m = M;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(C,DATA_TYPE,N,N,n,n);
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,N,M,n,m);

  /* Initialize array(s). */
  init_array (n, m, &alpha, &beta, POLYBENCH_ARRAY(C), POLYBENCH_ARRAY(A));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_syrk (n, m, alpha, beta, POLYBENCH_ARRAY(C), POLYBENCH_ARRAY(A));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(C)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(C);
  POLYBENCH_FREE_ARRAY(A);

  return 0;
}

