static
void print_array(int n,
		 DATA_TYPE POLYBENCH_2D(C,N,N,n,n))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("C");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
	if ((i * n + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, C[i][j]);
    }
  POLYBENCH_DUMP_END("C");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_syrk [[gnu::flatten, gnu::noinline]] (int n, int m,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,N,N,n,n),
		 DATA_TYPE POLYBENCH_2D(A,N,M,n,m))
{
  int i, j, k;

  // BLAS PARAMS
  // TRANS = 'N'
  // UPLO  = 'L'
  // =>  Form  C := alpha*A*A**T + beta*C.
  // A is NxM
  // C is NxN
#pragma scop
  /* Use local constants for loop bounds and scalars to help the compiler. */
  const int nn = _PB_N;
  const int mm = _PB_M;
  const DATA_TYPE alpha_ = alpha;
  const DATA_TYPE beta_  = beta;

  /*
   * Optimized structure:
   *  - Keep the outer i loop as in the original.
   *  - First scale C[i][0..i] by beta (same as original).
   *  - Then, for each j <= i, compute the inner product
   *        sum_k A[i][k] * A[j][k]
   *    using a k-innermost loop so that both A[i][k] and A[j][k]
   *    are accessed contiguously in memory (row-major layout).
   *
   * For each C[i][j], the order of accumulation over k is preserved:
   * we still visit k in increasing order and perform:
   *   C[i][j] = beta*C[i][j] + sum_k (alpha * A[i][k] * A[j][k])
   * Only the order in which different (i,j) pairs are updated is changed,
   * which is safe because they are independent.
   */
  for (i = 0; i < nn; i++) {
    /* Row pointers to avoid repeated address computations. */
    DATA_TYPE *Ci = C[i];
    DATA_TYPE *Ai = A[i];

    /* 1) Scale the lower-triangular part of row i by beta. */
    for (j = 0; j <= i; j++) {
      Ci[j] *= beta_;
    }

    /*
     * 2) SYRK update:
     *    For each j <= i, perform:
     *      C[i][j] += alpha * sum_{k=0..mm-1} A[i][k] * A[j][k]
     *
     *    The inner k loop now walks contiguously over both Ai and Aj
     *    rows, improving cache locality and enabling efficient
     *    auto-vectorization.
     */
    for (j = 0; j <= i; j++) {
      DATA_TYPE *Aj = A[j];
      DATA_TYPE cij = Ci[j];  /* already scaled by beta in the loop above */

      k = 0;

      /* Manually unroll the k-loop by 4.
       * This reduces loop overhead and typically helps the compiler
       * generate wider SIMD instructions. The tail loop handles
       * any remaining iterations when mm is not a multiple of 4.
       */
      int limit = mm & ~3;
      for (; k < limit; k += 4) {
        cij += alpha_ * Ai[k]     * Aj[k];
        cij += alpha_ * Ai[k + 1] * Aj[k + 1];
        cij += alpha_ * Ai[k + 2] * Aj[k + 2];
        cij += alpha_ * Ai[k + 3] * Aj[k + 3];
      }
      for (; k < mm; ++k) {
        cij += alpha_ * Ai[k] * Aj[k];
      }

      Ci[j] = cij;
    }
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int m = M;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(C,DATA_TYPE,N,N,n,n);
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,N,M,n,m);

  /* Initialize array(s). */
  init_array (n, m, &alpha, &beta, POLYBENCH_ARRAY(C), POLYBENCH_ARRAY(A));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_syrk (n, m, alpha, beta, POLYBENCH_ARRAY(C), POLYBENCH_ARRAY(A));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(C)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(C);
  POLYBENCH_FREE_ARRAY(A);

  return 0;
}
