      const DATA_TYPE *Aj = A_[j];  /* Row j of A */

      /* Scale once, keep C[i][j] in a register. */
      DATA_TYPE cij = Ci[j] * beta;

      /* Dot product of row i and row j of A:
           cij += alpha * (Ai · Aj)
         Accesses Ai[k] and Aj[k] are contiguous in memory. */
#pragma GCC ivdep
      for (k = 0; k < _PB_M; k++) {
        cij += alpha * Ai[k] * Aj[k];
      }

      /* Write back the updated lower-triangular entry. */
      Ci[j] = cij;
    }
  }
#pragma endscop

}


