/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimizations applied:
   - Introduce local restrict-qualified pointers to A and C to help
     the compiler with alias analysis and vectorization.
   - Separate the beta scaling of C from the rank-k update; this
     exposes two simpler loop nests and allows better optimization.
   - Reorder loops so that the innermost loop iterates over the k
     dimension; this makes accesses to rows of A contiguous in
     memory, improving cache locality and enabling SIMD.
   - Tile the k-dimension (KBLOCK) to keep working sets of A in L1/L2
     cache and reduce cache misses for large problem sizes.
   - Hoist frequently used row pointers (Ci, Ai) out of inner loops.
   - Preserve the exact mathematical order of the summation over k,
     so floating-point results remain as close as possible to the
     original implementation.
*/
static
void kernel_syrk[[gnu::flatten, gnu::noinline]](int n, int m,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,N,N,n,n),
		 DATA_TYPE POLYBENCH_2D(A,N,M,n,m))
{
  /* Local aliases with explicit 'restrict' to aid the optimizer.
     The parameter types are variable-length arrays (VLAs); here we
     cast them to restrict-qualified pointers to rows. */
  const int nn = n;
  const int mm = m;

  DATA_TYPE (*restrict C_)[nn] = (DATA_TYPE (*restrict)[nn]) C;
  DATA_TYPE (*restrict A_)[mm] = (DATA_TYPE (*restrict)[mm]) A;

  const DATA_TYPE alpha_local = alpha;
  const DATA_TYPE beta_local  = beta;

  /* k-block size: chosen to keep A's row segments in L1/L2 cache on
     typical x64 systems. Adjust if tuning for a specific machine. */
  enum { KBLOCK = 64 };

  int i, j, k;

  //BLAS PARAMS
  //TRANS = 'N'
  //UPLO  = 'L'
  // =>  Form  C := alpha*A*A**T + beta*C.
  //A is NxM
  //C is NxN

#pragma scop

  /* 1. Scale the lower triangular part of C by beta.
     This is identical to the original computation, but separated
     from the rank-k update to simplify the following loop nest. */
  for (i = 0; i < _PB_N; i++) {
    DATA_TYPE *restrict Ci = C_[i]; /* Row i of C */
    for (j = 0; j <= i; j++) {
      Ci[j] *= beta_local;
    }
  }

  /* 2. Symmetric rank-k update:
        C[i][j] += alpha * sum_k A[i][k] * A[j][k],   for j <= i.
     The innermost loop now runs over k so that we access rows of A
     contiguously in memory (A is stored row-major).
     We also tile the k-dimension by KBLOCK to improve cache reuse. */
  for (i = 0; i < _PB_N; i++) {
    DATA_TYPE *restrict Ci = C_[i];           /* Row i of C */
    const DATA_TYPE *restrict Ai = A_[i];     /* Row i of A */

    for (int kk = 0; kk < _PB_M; kk += KBLOCK) {
      const int kend = (kk + KBLOCK < _PB_M) ? (kk + KBLOCK) : _PB_M;
      const int klen = kend - kk;
      const DATA_TYPE *restrict Ai_block = Ai + kk;

      /* For each j <= i, compute a partial dot product over this
         k-block and accumulate into C[i][j].  The order of
         accumulation over k is preserved (0.._PB_M-1): we simply
         split it into contiguous blocks [0,KBLOCK), [KBLOCK,2*KBLOCK), ... */
      for (j = 0; j <= i; j++) {
        const DATA_TYPE *restrict Aj_block = A_[j] + kk;
        DATA_TYPE cij = Ci[j];

        for (k = 0; k < klen; k++) {
          cij += alpha_local * Ai_block[k] * Aj_block[k];
        }

        Ci[j] = cij;
      }
    }
  }

#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int m = M;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(C,DATA_TYPE,N,N,n,n);
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,N,M,n,m);

  /* Initialize array(s). */
  init_array (n, m, &alpha, &beta, POLYBENCH_ARRAY(C), POLYBENCH_ARRAY(A));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_syrk (n, m, alpha, beta, POLYBENCH_ARRAY(C), POLYBENCH_ARRAY(A));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(C)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(C);
  POLYBENCH_FREE_ARRAY(A);

